def evaluate(self, task, expression):
    if isinstance(expression, Operator):
        return expression._matches(task)
    else:
        return self._eval(task, expression, **task.data)

def collect_entities(sent, ranks, stopwords, spacy_nlp):
    global DEBUG
    sent_text = ' '.join([w.raw for w in sent])
    if DEBUG:
        print('sent:', sent_text)
    for ent in spacy_nlp(sent_text).ents:
        if DEBUG:
            print('NER:', ent.label_, ent.text)
        if ent.label_ not in ['CARDINAL'] and ent.text.lower() not in stopwords:
            (w_ranks, w_ids) = find_entity(sent, ranks, ent.text.split(' '), 0)
            if w_ranks and w_ids:
                rl = RankedLexeme(text=ent.text.lower(), rank=w_ranks, ids=w_ids, pos='np', count=1)
                if DEBUG:
                    print(rl)
                yield rl

def _api_call(self, method_name, *args, **kwargs):
    params = kwargs.setdefault('params', {})
    params.update({'key': self._apikey})
    if self._token is not None:
        params.update({'token': self._token})
    http_method = getattr(requests, method_name)
    return http_method(TRELLO_URL + self._url, *args, **kwargs)

def get_evidences_by_pmid(graph: BELGraph, pmids: Union[str, Iterable[str]]):
    result = defaultdict(set)
    for (_, _, _, data) in filter_edges(graph, build_pmid_inclusion_filter(pmids)):
        result[data[CITATION][CITATION_REFERENCE]].add(data[EVIDENCE])
    return dict(result)

def _search_folder_for_item_or_folder(name, folder_id):
    session.token = verify_credentials()
    children = session.communicator.folder_children(session.token, folder_id)
    for folder in children['folders']:
        if folder['name'] == name:
            return (False, folder['folder_id'])
    for item in children['items']:
        if item['name'] == name:
            return (True, item['item_id'])
    return (False, -1)

def _get_queues(g, queues, edge, edge_type):
    INT = numbers.Integral
    if isinstance(queues, INT):
        queues = [queues]
    elif queues is None:
        if edge is not None:
            if isinstance(edge, tuple):
                if isinstance(edge[0], INT) and isinstance(edge[1], INT):
                    queues = [g.edge_index[edge]]
            elif isinstance(edge[0], collections.Iterable):
                if np.array([len(e) == 2 for e in edge]).all():
                    queues = [g.edge_index[e] for e in edge]
            else:
                queues = [g.edge_index[edge]]
        elif edge_type is not None:
            if isinstance(edge_type, collections.Iterable):
                edge_type = set(edge_type)
            else:
                edge_type = set([edge_type])
            tmp = []
            for e in g.edges():
                if g.ep(e, 'edge_type') in edge_type:
                    tmp.append(g.edge_index[e])
            queues = np.array(tmp, int)
        if queues is None:
            queues = range(g.number_of_edges())
    return queues

def create_project(config_data):
    env = deepcopy(dict(os.environ))
    env[str('DJANGO_SETTINGS_MODULE')] = str('{0}.settings'.format(config_data.project_name))
    env[str('PYTHONPATH')] = str(os.pathsep.join(map(shlex_quote, sys.path)))
    kwargs = {}
    args = []
    if config_data.template:
        kwargs['template'] = config_data.template
    args.append(config_data.project_name)
    if config_data.project_directory:
        args.append(config_data.project_directory)
        if not os.path.exists(config_data.project_directory):
            os.makedirs(config_data.project_directory)
    base_cmd = 'django-admin.py'
    start_cmds = [os.path.join(os.path.dirname(sys.executable), base_cmd)]
    start_cmd_pnodes = ['Scripts']
    start_cmds.extend([os.path.join(os.path.dirname(sys.executable), pnode, base_cmd) for pnode in start_cmd_pnodes])
    start_cmd = [base_cmd]
    for p in start_cmds:
        if os.path.exists(p):
            start_cmd = [sys.executable, p]
            break
    cmd_args = start_cmd + ['startproject'] + args
    if config_data.verbose:
        sys.stdout.write('Project creation command: {0}\n'.format(' '.join(cmd_args)))
    try:
        output = subprocess.check_output(cmd_args, stderr=subprocess.STDOUT)
        sys.stdout.write(output.decode('utf-8'))
    except subprocess.CalledProcessError as e:
        if config_data.verbose:
            sys.stdout.write(e.output.decode('utf-8'))
        raise

def known_context_patterns(self, val):

    def create_pat_from_dict(val):
        if 'tag' in val:
            pat = ArticleContextPattern(tag=val['tag'])
            if 'attr' in val:
                pat.attr = val['attr']
                pat.value = val['value']
        elif 'attr' in val:
            pat = ArticleContextPattern(attr=val['attr'], value=val['value'])
        if 'domain' in val:
            pat.domain = val['domain']
        return pat
    if isinstance(val, list):
        self._known_context_patterns = [x if isinstance(x, ArticleContextPattern) else create_pat_from_dict(x) for x in val] + self.known_context_patterns
    elif isinstance(val, ArticleContextPattern):
        self._known_context_patterns.insert(0, val)
    elif isinstance(val, dict):
        self._known_context_patterns.insert(0, create_pat_from_dict(val))
    else:
        raise Exception('Unknown type: {}. Use a ArticleContextPattern.'.format(type(val)))

def copy_directory(self, relativePath, newRelativePath, overwrite=False, raiseError=True, ntrials=3):
    assert isinstance(raiseError, bool), 'raiseError must be boolean'
    assert isinstance(overwrite, bool), 'overwrite must be boolean'
    assert isinstance(ntrials, int), 'ntrials must be integer'
    assert ntrials > 0, 'ntrials must be >0'
    relativePath = self.to_repo_relative_path(path=relativePath, split=False)
    if relativePath == '':
        m = 'Copying to repository main directory is not possible'
        assert not raiseError, m
        return (False, m)
    realPath = os.path.join(self.__path, relativePath)
    (parentRealPath, dirName) = os.path.split(realPath)
    parentRelativePath = os.path.dirname(relativePath)
    if not self.is_repository_directory(relativePath):
        m = "Directory '%s' is not a tracked repository directory" % relativePath
        assert not raiseError, m
        return (False, m)
    newRelativePath = self.to_repo_relative_path(path=newRelativePath, split=False)
    newRealPath = os.path.join(self.__path, newRelativePath)
    (newParentRealPath, newDirName) = os.path.split(newRealPath)
    newParentRelativePath = os.path.dirname(newRelativePath)
    if realPath == newRealPath:
        m = 'Copying to the same directory is not possible'
        assert not raiseError, m
        return (False, m)
    if self.is_repository_directory(newRelativePath):
        m = "Directory '%s' is a tracked repository directory" % newRelativePath
        assert not raiseError, m
        return (False, m)
    if os.path.isdir(newRealPath):
        if overwrite:
            try:
                shutil.rmtree(newRealPath)
            except Exception as err:
                assert not raiseError, str(err)
                return (False, str(err))
        else:
            error = "New directory path '%s' already exist on disk. Set overwrite to True" % (newRealPath,)
            assert not raiseError, error
            return (False, error)
    try:
        (success, reason) = self.add_directory(newParentRelativePath, raiseError=False, ntrials=ntrials)
    except Exception as err:
        reason = 'Unable to add directory (%s)' % str(err)
        success = False
    if not success:
        assert not raiseError, reason
        return (False, reason)
    LR = Locker(filePath=None, lockPass=str(uuid.uuid1()), lockPath=os.path.join(self.__path, self.__repoLock))
    (acquired, code) = LR.acquire_lock()
    if not acquired:
        m = 'code %s. Unable to aquire the repository lock. You may try again!' % (code,)
        assert raiseError, Exception(m)
        return (False, m)
    try:
        repo = self.__load_repository_pickle_file(os.path.join(self.__path, self.__repoFile))
        self.__repo['walk_repo'] = repo['walk_repo']
    except Exception as err:
        LR.release_lock()
        assert not raiseError, Exception(str(err))
        return (False, m)
    L0 = Locker(filePath=None, lockPass=str(uuid.uuid1()), lockPath=os.path.join(parentRealPath, self.__dirLock))
    (acquired, code) = L0.acquire_lock()
    if not acquired:
        LR.release_lock()
        error = "Code %s. Unable to aquire the lock when adding '%s'. All prior directories were added. You may try again, to finish adding directory" % (code, dirPath)
        assert not raiseError, error
        return (False, error)
    L1 = None
    if parentRealPath != newParentRealPath:
        L1 = Locker(filePath=None, lockPass=str(uuid.uuid1()), lockPath=os.path.join(newParentRealPath, self.__dirLock))
        (acquired, code) = L1.acquire_lock()
        if not acquired:
            L0.release_lock()
            LR.release_lock()
            error = "Code %s. Unable to aquire the lock when adding '%s'. All prior directories were added. You may try again, to finish adding directory" % (code, dirPath)
            assert not raiseError, error
            return (False, error)
    error = None
    for _trial in range(ntrials):
        try:
            assert self.is_repository_directory(relativePath), "Directory '%s' is not anymore a tracked repository directory" % relativePath
            assert not self.is_repository_directory(newRelativePath), "Directory '%s' has become a tracked repository directory" % relativePath
            dirList = self.__get_repository_parent_directory(relativePath=relativePath)
            assert dirList is not None, "Given relative path '%s' is not a repository directory" % (relativePath,)
            newDirList = self.__get_repository_parent_directory(relativePath=newRelativePath)
            assert newDirList is not None, "Given new relative path '%s' parent directory is not a repository directory" % (newRelativePath,)
            _dirDict = [nd for nd in dirList if isinstance(nd, dict)]
            _dirDict = [nd for nd in _dirDict if dirName in nd]
            assert len(_dirDict) == 1, 'This should not have happened. Directory not found in repository. Please report issue'
            _newDirDict = [nd for nd in newDirList if isinstance(nd, dict)]
            _newDirDict = [nd for nd in _newDirDict if newDirName in nd]
            assert len(_newDirDict) == 0, 'This should not have happened. New directory is found in repository. Please report issue'
            _newDirDict = copy.deepcopy(_dirDict[0])
            if dirName != newDirName:
                _newDirDict[newDirName] = _newDirDict.pop(dirName)
            copy_tree(realPath, newRealPath)
            newDirList.append(_newDirDict)
            self.__save_dirinfo(description=None, dirInfoPath=newParentRelativePath, create=False)
        except Exception as err:
            error = str(err)
            if self.DEBUG_PRINT_FAILED_TRIALS:
                print('Trial %i failed in Repository.%s (%s). Set Repository.DEBUG_PRINT_FAILED_TRIALS to False to mute' % (_trial, inspect.stack()[1][3], str(error)))
        else:
            error = None
            break
    if error is None:
        (_, error) = self.__save_repository_pickle_file(lockFirst=False, raiseError=False)
    LR.release_lock()
    L0.release_lock()
    if L1 is not None:
        L1.release_lock()
    assert error is None or not raiseError, "Unable to copy directory '%s' to '%s' after %i trials (%s)" % (relativePath, newRelativePath, ntrials, error)
    return (error is None, error)

