def stopProducing(self):
    self._finish(True)
    if self._deferred and self._sent < self.length:
        self._deferred.errback(Exception('Consumer asked to stop production of request body (%d sent out of %d)' % (self._sent, self.length)))

def Cp(compound_string, T, mass=1.0):
    (formula, phase) = _split_compound_string_(compound_string)
    TK = T + 273.15
    compound = compounds[formula]
    result = compound.Cp(phase, TK)
    return _finalise_result_(compound, result, mass)

def env_to_dict(prefix, names):
    env = {}
    for name in names:
        env[name] = ENV.get('_'.join([prefix, name]))
        if env[name] is None:
            return None
    return env

def best_other_class(logits, exclude):
    other_logits = logits - onehot_like(logits, exclude, value=np.inf)
    return np.argmax(other_logits)

def response_text(self, content, escape=False):
    self._check_parse()
    content = self._transcoding(content)
    if escape:
        if six.PY2:
            content = cgi.escape(content)
        else:
            import html
            content = html.escape(content)
    response = TextReply(message=self.__message, content=content).render()
    return self._encrypt_response(response)

def inverse_kinematics(self, start=0, end=1e+100, states=None, max_force=20):
    zeros = None
    if max_force > 0:
        self.skeleton.enable_motors(max_force)
        zeros = np.zeros(self.skeleton.num_dofs)
    for _ in self.follow_markers(start, end, states):
        if zeros is not None:
            self.skeleton.set_target_angles(zeros)
        yield self.skeleton.joint_angles

