    return Address(base58.encode(hexlify(data + checksum)))

def write(self, mi_cmd_to_write, timeout_sec=DEFAULT_GDB_TIMEOUT_SEC, raise_error_on_timeout=True, read_response=True):
    self.verify_valid_gdb_subprocess()
    if timeout_sec < 0:
        self.logger.warning('timeout_sec was negative, replacing with 0')
        timeout_sec = 0
    if type(mi_cmd_to_write) in [str, unicode]:
        pass
    elif type(mi_cmd_to_write) == list:
        mi_cmd_to_write = '\n'.join(mi_cmd_to_write)
    else:
        raise TypeError('The gdb mi command must a be str or list. Got ' + str(type(mi_cmd_to_write)))
    self.logger.debug('writing: %s', mi_cmd_to_write)
    if not mi_cmd_to_write.endswith('\n'):
        mi_cmd_to_write_nl = mi_cmd_to_write + '\n'
    else:
        mi_cmd_to_write_nl = mi_cmd_to_write
    if USING_WINDOWS:
        outputready = [self.stdin_fileno]
    else:
        (_, outputready, _) = select.select([], self.write_list, [], timeout_sec)
    for fileno in outputready:
        if fileno == self.stdin_fileno:
            self.gdb_process.stdin.write(mi_cmd_to_write_nl.encode())
            self.gdb_process.stdin.flush()
        else:
            self.logger.error('got unexpected fileno %d' % fileno)
    if read_response is True:
        return self.get_gdb_response(timeout_sec=timeout_sec, raise_error_on_timeout=raise_error_on_timeout)
    else:
        return []

def setSweep(self, sweep=0, force=False):
    if sweep is None or sweep is False:
        sweep = 0
    if sweep < 0:
        sweep = self.sweeps - sweep
        if sweep < 0:
            sweep = 0
    if sweep > self.sweeps - 1:
        print(" !! there aren't %d sweeps. Reverting to last (%d) sweep." % (sweep, self.sweeps - 1))
        sweep = self.sweeps - 1
    sweep = int(sweep)
    try:
        if self.currentSweep == sweep and force == False:
            return
        self.currentSweep = sweep
        self.dataY = self.block.segments[sweep].analogsignals[self.channel]
        self.dataY = np.array(self.dataY)
        (B1, B2) = self.baseline
        if B1 == None:
            B1 = 0
        else:
            B1 = B1 * self.rate
        if B2 == None:
            B2 == self.sweepSize
        else:
            B2 = B2 * self.rate
            self.dataY -= np.average(self.dataY[self.baseline[0] * self.rate:self.baseline[1] * self.rate])
        self.sweep_genXs()
        self.sweep_decimate()
        self.generate_protocol(sweep=sweep)
        self.dataStart = self.sweepInterval * self.currentSweep
    except Exception:
        print('#' * 400, '\n', traceback.format_exc(), '\n', '#' * 400)
    return (self.dataX, self.dataY)

