def scanProcessForMapping(pid, searchPortion, isExactMatch=False, ignoreCase=False):
    try:
        try:
            pid = int(pid)
        except ValueError as e:
            sys.stderr.write('Expected an integer, got %s for pid.\n' % (str(type(pid)),))
            raise e
        with open('/proc/%d/maps' % (pid,), 'r') as f:
            contents = f.read()
        lines = contents.split('\n')
        matchedMappings = []
        if isExactMatch is True:
            if ignoreCase is False:
                isMatch = lambda searchFor, searchIn: bool(searchFor == searchIn)
            else:
                isMatch = lambda searchFor, searchIn: bool(searchFor.lower() == searchIn.lower())
        elif ignoreCase is False:
            isMatch = lambda searchFor, searchIn: bool(searchFor in searchIn)
        else:
            isMatch = lambda searchFor, searchIn: bool(searchFor.lower() in searchIn.lower())
        for line in lines:
            portion = ' '.join(line.split(' ')[5:]).lstrip()
            if isMatch(searchPortion, portion):
                matchedMappings.append('\t' + line)
        if len(matchedMappings) == 0:
            return None
        cmdline = getProcessCommandLineStr(pid)
        owner = getProcessOwnerStr(pid)
        return {'searchPortion': searchPortion, 'pid': pid, 'owner': owner, 'cmdline': cmdline, 'matchedMappings': matchedMappings}
    except OSError:
        return None
    except IOError:
        return None
    except FileNotFoundError:
        return None
    except PermissionError:
        return None

def plot_T_dependent_property(self, Tmin=None, Tmax=None, methods=[], pts=50, only_valid=True, order=0):
    if not has_matplotlib:
        raise Exception('Optional dependency matplotlib is required for plotting')
    if Tmin is None:
        if self.Tmin is not None:
            Tmin = self.Tmin
        else:
            raise Exception('Minimum temperature could not be auto-detected; please provide it')
    if Tmax is None:
        if self.Tmax is not None:
            Tmax = self.Tmax
        else:
            raise Exception('Maximum temperature could not be auto-detected; please provide it')
    if not methods:
        if self.user_methods:
            methods = self.user_methods
        else:
            methods = self.all_methods
    Ts = np.linspace(Tmin, Tmax, pts)
    if order == 0:
        for method in methods:
            if only_valid:
                (properties, Ts2) = ([], [])
                for T in Ts:
                    if self.test_method_validity(T, method):
                        try:
                            p = self.calculate(T=T, method=method)
                            if self.test_property_validity(p):
                                properties.append(p)
                                Ts2.append(T)
                        except:
                            pass
                plt.semilogy(Ts2, properties, label=method)
            else:
                properties = [self.calculate(T=T, method=method) for T in Ts]
                plt.semilogy(Ts, properties, label=method)
        plt.ylabel(self.name + ', ' + self.units)
        plt.title(self.name + ' of ' + self.CASRN)
    elif order > 0:
        for method in methods:
            if only_valid:
                (properties, Ts2) = ([], [])
                for T in Ts:
                    if self.test_method_validity(T, method):
                        try:
                            p = self.calculate_derivative(T=T, method=method, order=order)
                            properties.append(p)
                            Ts2.append(T)
                        except:
                            pass
                plt.semilogy(Ts2, properties, label=method)
            else:
                properties = [self.calculate_derivative(T=T, method=method, order=order) for T in Ts]
                plt.semilogy(Ts, properties, label=method)
        plt.ylabel(self.name + ', ' + self.units + '/K^%d derivative of order %d' % (order, order))
        plt.title(self.name + ' derivative of order %d' % order + ' of ' + self.CASRN)
    plt.legend(loc='best')
    plt.xlabel('Temperature, K')
    plt.show()

