def run(self, inputcode, iterations=None, run_forever=False, frame_limiter=False, verbose=False, break_on_error=False):
    source = None
    filename = None
    if os.path.isfile(inputcode):
        source = open(inputcode).read()
        filename = inputcode
    elif isinstance(inputcode, basestring):
        filename = 'shoebot_code'
        source = inputcode
    self._load_namespace(self._namespace, filename)
    self._executor = executor = LiveExecution(source, ns=self._namespace, filename=filename)
    try:
        if not iterations:
            if run_forever:
                iterations = None
            else:
                iterations = 1
        iteration = 0
        event = None
        while iteration != iterations and (not event_is(event, QUIT_EVENT)):
            self._run_frame(executor, limit=frame_limiter, iteration=iteration)
            if iteration == 0:
                self._initial_namespace = copy.copy(self._namespace)
            iteration += 1
            while self._should_run(iteration, iterations) and event is None:
                iteration += 1
                self._run_frame(executor, limit=frame_limiter, iteration=iteration)
                event = next_event()
                if not event:
                    self._canvas.sink.main_iteration()
            while run_forever:
                while event is None:
                    self._canvas.sink.main_iteration()
                    event = next_event(block=True, timeout=0.05)
                    if not event:
                        self._canvas.sink.main_iteration()
                if event.type == QUIT_EVENT:
                    break
                elif event.type == SOURCE_CHANGED_EVENT:
                    while event and event.type == SOURCE_CHANGED_EVENT:
                        event = next_event(block=True, timeout=0.001)
                elif event.type == SET_WINDOW_TITLE:
                    self._canvas.sink.set_title(event.data)
                event = None
                break
    except Exception as e:
        import sys
        if verbose:
            errmsg = traceback.format_exc()
        else:
            errmsg = simple_traceback(e, executor.known_good or '')
        (print >> sys.stderr, errmsg)
        if break_on_error:
            raise

def retrySQL(timeoutSec=60 * 5, logger=None):
    if logger is None:
        logger = logging.getLogger(__name__)

    def retryFilter(e, args, kwargs):
        if isinstance(e, (pymysql.InternalError, pymysql.OperationalError)):
            if e.args and e.args[0] in _ALL_RETRIABLE_ERROR_CODES:
                return True
        elif isinstance(e, pymysql.Error):
            if e.args and inspect.isclass(e.args[0]) and issubclass(e.args[0], socket_error):
                return True
        return False
    retryExceptions = tuple([pymysql.InternalError, pymysql.OperationalError, pymysql.Error])
    return make_retry_decorator(timeoutSec=timeoutSec, initialRetryDelaySec=0.1, maxRetryDelaySec=10, retryExceptions=retryExceptions, retryFilter=retryFilter, logger=logger)

