    self.all = []
    all_content = '('
    while self.current.kind != tk.OP or self.current.value not in ')]':
        if self.current.kind in (tk.NL, tk.COMMENT):
            pass
        elif self.current.kind == tk.STRING or self.current.value == ',':
            all_content += self.current.value
        else:
            raise AllError('Unexpected token kind in  __all__: {!r}. '.format(self.current.kind))
        self.stream.move()
    self.consume(tk.OP)
    all_content += ')'
    try:
        self.all = eval(all_content, {})
    except BaseException as e:
        raise AllError('Could not evaluate contents of __all__.\x08The value was {}. The exception was:\n{}'.format(all_content, e))

