def warn_message(self, message, fh=None, prefix='[warn]:', suffix='...'):
    msg = prefix + message + suffix
    fh = fh or sys.stdout
    if fh is sys.stdout:
        termcolor.cprint(msg, color='yellow')
    else:
        fh.write(msg)
    pass

def sphinx(ctx, browse=False, clean=False, watchdog=False, kill=False, status=False, opts=''):
    cfg = config.load()
    if kill or status:
        if not watchdogctl(ctx, kill=kill):
            notify.info('No process bound to port {}'.format(ctx.rituals.docs.watchdog.port))
