def draw_boxes_and_labels_to_image(image, classes, coords, scores, classes_list, is_center=True, is_rescale=True, save_name=None):
    if len(coords) != len(classes):
        raise AssertionError('number of coordinates and classes are equal')
    if len(scores) > 0 and len(scores) != len(classes):
        raise AssertionError('number of scores and classes are equal')
    image = image.copy()
    (imh, imw) = image.shape[0:2]
    thick = int((imh + imw) // 430)
    for (i, _v) in enumerate(coords):
        if is_center:
            (x, y, x2, y2) = tl.prepro.obj_box_coord_centroid_to_upleft_butright(coords[i])
        else:
            (x, y, x2, y2) = coords[i]
        if is_rescale:
            (x, y, x2, y2) = tl.prepro.obj_box_coord_scale_to_pixelunit([x, y, x2, y2], (imh, imw))
        cv2.rectangle(image, (int(x), int(y)), (int(x2), int(y2)), [0, 255, 0], thick)
        cv2.putText(image, classes_list[classes[i]] + (' %.2f' % scores[i] if len(scores) != 0 else ' '), (int(x), int(y)), 0, 0.0015 * imh, [0, 0, 256], int(thick / 2) + 1)
    if save_name is not None:
        save_image(image, save_name)
    return image

def update_pareto_optimal_tuples(self, new_label):
    assert isinstance(new_label, LabelTime)
    if self._labels:
        assert new_label.departure_time <= self._labels[-1].departure_time
        best_later_departing_arrival_time = self._labels[-1].arrival_time_target
    else:
        best_later_departing_arrival_time = float('inf')
    walk_to_target_arrival_time = new_label.departure_time + self._walk_to_target_duration
    best_arrival_time = min(walk_to_target_arrival_time, best_later_departing_arrival_time, new_label.arrival_time_target)
    if new_label.arrival_time_target < walk_to_target_arrival_time and new_label.arrival_time_target < best_later_departing_arrival_time:
        self._labels.append(LabelTime(new_label.departure_time, best_arrival_time))
        return True
    else:
        return False

def pgen_lsp(times, mags, errs, magsarefluxes=False, startp=None, endp=None, stepsize=0.0001, autofreq=True, nbestpeaks=5, periodepsilon=0.1, sigclip=10.0, nworkers=None, workchunksize=None, glspfunc=_glsp_worker_withtau, verbose=True):
    (stimes, smags, serrs) = sigclip_magseries(times, mags, errs, magsarefluxes=magsarefluxes, sigclip=sigclip)
    nzind = npnonzero(serrs)
    (stimes, smags, serrs) = (stimes[nzind], smags[nzind], serrs[nzind])
    if len(stimes) > 9 and len(smags) > 9 and (len(serrs) > 9):
        if startp:
            endf = 1.0 / startp
        else:
            endf = 1.0 / 0.1
        if endp:
            startf = 1.0 / endp
        else:
            startf = 1.0 / (stimes.max() - stimes.min())
        if not autofreq:
            omegas = 2 * pi_value * nparange(startf, endf, stepsize)
            if verbose:
                LOGINFO('using %s frequency points, start P = %.3f, end P = %.3f' % (omegas.size, 1.0 / endf, 1.0 / startf))
        else:
            freqs = get_frequency_grid(stimes, minfreq=startf, maxfreq=endf)
            omegas = 2 * pi_value * freqs
            if verbose:
                LOGINFO('using autofreq with %s frequency points, start P = %.3f, end P = %.3f' % (omegas.size, 1.0 / freqs.max(), 1.0 / freqs.min()))
        if not nworkers or nworkers > NCPUS:
            nworkers = NCPUS
            if verbose:
                LOGINFO('using %s workers...' % nworkers)
        pool = Pool(nworkers)
        tasks = [(stimes, smags, serrs, x) for x in omegas]
        if workchunksize:
            lsp = pool.map(glspfunc, tasks, chunksize=workchunksize)
        else:
            lsp = pool.map(glspfunc, tasks)
        pool.close()
        pool.join()
        del pool
        lsp = nparray(lsp)
        periods = 2.0 * pi_value / omegas
        finitepeakind = npisfinite(lsp)
        finlsp = lsp[finitepeakind]
        finperiods = periods[finitepeakind]
        try:
            bestperiodind = npargmax(finlsp)
        except ValueError:
            LOGERROR('no finite periodogram values for this mag series, skipping...')
            return {'bestperiod': npnan, 'bestlspval': npnan, 'nbestpeaks': nbestpeaks, 'nbestlspvals': None, 'nbestperiods': None, 'lspvals': None, 'omegas': omegas, 'periods': None, 'method': 'gls', 'kwargs': {'startp': startp, 'endp': endp, 'stepsize': stepsize, 'autofreq': autofreq, 'periodepsilon': periodepsilon, 'nbestpeaks': nbestpeaks, 'sigclip': sigclip}}
        sortedlspind = npargsort(finlsp)[::-1]
        sortedlspperiods = finperiods[sortedlspind]
        sortedlspvals = finlsp[sortedlspind]
        (nbestperiods, nbestlspvals, peakcount) = ([finperiods[bestperiodind]], [finlsp[bestperiodind]], 1)
        prevperiod = sortedlspperiods[0]
        for (period, lspval) in zip(sortedlspperiods, sortedlspvals):
            if peakcount == nbestpeaks:
                break
            perioddiff = abs(period - prevperiod)
            bestperiodsdiff = [abs(period - x) for x in nbestperiods]
            if perioddiff > periodepsilon * prevperiod and all((x > periodepsilon * period for x in bestperiodsdiff)):
                nbestperiods.append(period)
                nbestlspvals.append(lspval)
                peakcount = peakcount + 1
            prevperiod = period
        return {'bestperiod': finperiods[bestperiodind], 'bestlspval': finlsp[bestperiodind], 'nbestpeaks': nbestpeaks, 'nbestlspvals': nbestlspvals, 'nbestperiods': nbestperiods, 'lspvals': lsp, 'omegas': omegas, 'periods': periods, 'method': 'gls', 'kwargs': {'startp': startp, 'endp': endp, 'stepsize': stepsize, 'autofreq': autofreq, 'periodepsilon': periodepsilon, 'nbestpeaks': nbestpeaks, 'sigclip': sigclip}}
    else:
        LOGERROR('no good detections for these times and mags, skipping...')
        return {'bestperiod': npnan, 'bestlspval': npnan, 'nbestpeaks': nbestpeaks, 'nbestlspvals': None, 'nbestperiods': None, 'lspvals': None, 'omegas': None, 'periods': None, 'method': 'gls', 'kwargs': {'startp': startp, 'endp': endp, 'stepsize': stepsize, 'autofreq': autofreq, 'periodepsilon': periodepsilon, 'nbestpeaks': nbestpeaks, 'sigclip': sigclip}}

def _phase_kuramoto(self, teta, t, argv):
    index = argv
    phase = 0
    for k in range(0, self._num_osc):
        if self.has_connection(index, k) == True:
            phase += self._negative_weight * math.sin(self._phases[k] - teta)
        else:
            phase += self._positive_weight * math.sin(self._phases[k] - teta)
    return phase / self._reduction

