def _load_key(key_object):
    if key_object.algorithm == 'ec':
        (curve_type, details) = key_object.curve
        if curve_type != 'named':
            raise AsymmetricKeyError('OS X only supports EC keys using named curves')
        if details not in set(['secp256r1', 'secp384r1', 'secp521r1']):
            raise AsymmetricKeyError(pretty_message('\n                OS X only supports EC keys using the named curves secp256r1,\n                secp384r1 and secp521r1\n                '))
    elif key_object.algorithm == 'dsa' and key_object.hash_algo == 'sha2':
        raise AsymmetricKeyError(pretty_message('\n            OS X only supports DSA keys based on SHA1 (2048 bits or less) - this\n            key is based on SHA2 and is %s bits\n            ', key_object.bit_size))
    elif key_object.algorithm == 'dsa' and key_object.hash_algo is None:
        raise IncompleteAsymmetricKeyError(pretty_message('\n            The DSA key does not contain the necessary p, q and g parameters\n            and can not be used\n            '))
    if isinstance(key_object, keys.PublicKeyInfo):
        source = key_object.dump()
        key_class = Security.kSecAttrKeyClassPublic
    else:
        source = key_object.unwrap().dump()
        key_class = Security.kSecAttrKeyClassPrivate
    cf_source = None
    cf_dict = None
    cf_output = None
    try:
        cf_source = CFHelpers.cf_data_from_bytes(source)
        key_type = {'dsa': Security.kSecAttrKeyTypeDSA, 'ec': Security.kSecAttrKeyTypeECDSA, 'rsa': Security.kSecAttrKeyTypeRSA}[key_object.algorithm]
        cf_dict = CFHelpers.cf_dictionary_from_pairs([(Security.kSecAttrKeyType, key_type), (Security.kSecAttrKeyClass, key_class), (Security.kSecAttrCanSign, CoreFoundation.kCFBooleanTrue), (Security.kSecAttrCanVerify, CoreFoundation.kCFBooleanTrue)])
        error_pointer = new(CoreFoundation, 'CFErrorRef *')
        sec_key_ref = Security.SecKeyCreateFromData(cf_dict, cf_source, error_pointer)
        handle_cf_error(error_pointer)
        if key_class == Security.kSecAttrKeyClassPublic:
            return PublicKey(sec_key_ref, key_object)
        if key_class == Security.kSecAttrKeyClassPrivate:
            return PrivateKey(sec_key_ref, key_object)
    finally:
        if cf_source:
            CoreFoundation.CFRelease(cf_source)
        if cf_dict:
            CoreFoundation.CFRelease(cf_dict)
        if cf_output:
            CoreFoundation.CFRelease(cf_output)

def _rc_dbsize(self):
    result = 0
    for (alias, redisent) in iteritems(self.redises):
        if alias.find('_slave') == -1:
            continue
        result += redisent.dbsize()
    return result

def make_request(self, url, method='get', headers=None, data=None, callback=None, errors=STRICT, verify=False, timeout=None, **params):
    error_modes = (STRICT, GRACEFUL, IGNORE)
    error_mode = errors or GRACEFUL
    if error_mode.lower() not in error_modes:
        raise ValueError('Possible values for errors argument are: %s' % ','.join(error_modes))
    if callback is None:
        callback = self._default_resp_callback
    request = getattr(requests, method.lower())
    log.debug('* Request URL: %s' % url)
    log.debug('* Request method: %s' % method)
    log.debug('* Request query params: %s' % params)
    log.debug('* Request headers: %s' % headers)
    log.debug('* Request timeout: %s' % timeout)
    r = request(url, headers=headers, data=data, verify=verify, timeout=timeout, params=params)
    log.debug('* r.url: %s' % r.url)
    try:
        r.raise_for_status()
        return callback(r)
    except Exception as e:
        return self._with_error_handling(r, e, error_mode, self.response_format)

def _add_option(self, option):
    if option.name in self.options:
        raise ValueError('name already in use')
    if option.abbreviation in self.abbreviations:
        raise ValueError('abbreviation already in use')
    if option.name in [arg.name for arg in self.positional_args]:
        raise ValueError('name already in use by a positional argument')
    self.options[option.name] = option
    if option.abbreviation:
        self.abbreviations[option.abbreviation] = option
    self.option_order.append(option.name)

def GetIndentLevel(line):
    indent = Match('^( *)\\S', line)
    if indent:
        return len(indent.group(1))
    else:
        return 0

def _map_oids(oids):
    new_oids = set()
    for oid in oids:
        if oid in _oid_map:
            new_oids |= _oid_map[oid]
    return oids | new_oids

