def extract_from_image(self, image, size=1, pad=True, pad_max=None, antialiased=True, prevent_zero_size=True):
    from .bbs import BoundingBox
    assert image.ndim in [2, 3], 'Expected image of shape (H,W,[C]), got shape %s.' % (image.shape,)
    if len(self.coords) == 0 or size <= 0:
        if prevent_zero_size:
            return np.zeros((1, 1) + image.shape[2:], dtype=image.dtype)
        return np.zeros((0, 0) + image.shape[2:], dtype=image.dtype)
    xx = self.xx_int
    yy = self.yy_int
    sizeh = (size - 1) / 2
    x1 = np.min(xx) - sizeh
    y1 = np.min(yy) - sizeh
    x2 = np.max(xx) + 1 + sizeh
    y2 = np.max(yy) + 1 + sizeh
    bb = BoundingBox(x1=x1, y1=y1, x2=x2, y2=y2)
    if len(self.coords) == 1:
        return bb.extract_from_image(image, pad=pad, pad_max=pad_max, prevent_zero_size=prevent_zero_size)
    heatmap = self.draw_lines_heatmap_array(image.shape[0:2], alpha=1.0, size=size, antialiased=antialiased)
    if image.ndim == 3:
        heatmap = np.atleast_3d(heatmap)
    image_masked = image.astype(np.float32) * heatmap
    extract = bb.extract_from_image(image_masked, pad=pad, pad_max=pad_max, prevent_zero_size=prevent_zero_size)
    return np.clip(np.round(extract), 0, 255).astype(np.uint8)

