def parse_signature_type_comment(type_comment):
    try:
        result = ast3.parse(type_comment, '<func_type>', 'func_type')
    except SyntaxError:
        raise ValueError(f'invalid function signature type comment: {type_comment!r}')
    assert isinstance(result, ast3.FunctionType)
    if len(result.argtypes) == 1:
        argtypes = result.argtypes[0]
    else:
        argtypes = result.argtypes
    return (argtypes, result.returns)

def dict_gather(comm, d, op='mean', assert_all_have_data=True):
    if comm is None:
        return d
    alldicts = comm.allgather(d)
    size = comm.size
    k2li = defaultdict(list)
    for d in alldicts:
        for (k, v) in d.items():
            k2li[k].append(v)
    result = {}
    for (k, li) in k2li.items():
        if assert_all_have_data:
            assert len(li) == size, "only %i out of %i MPI workers have sent '%s'" % (len(li), size, k)
        if op == 'mean':
            result[k] = np.mean(li, axis=0)
        elif op == 'sum':
            result[k] = np.sum(li, axis=0)
        else:
            assert 0, op
    return result

def line(self, p1, p2, resolution=1):
    xdiff = max(p1.x, p2.x) - min(p1.x, p2.x)
    ydiff = max(p1.y, p2.y) - min(p1.y, p2.y)
    xdir = [-1, 1][int(p1.x <= p2.x)]
    ydir = [-1, 1][int(p1.y <= p2.y)]
    r = int(round(max(xdiff, ydiff)))
    if r == 0:
        return
    for i in range((r + 1) * resolution):
        x = p1.x
        y = p1.y
        if xdiff:
            x += float(i) * xdiff / r * xdir / resolution
        if ydiff:
            y += float(i) * ydiff / r * ydir / resolution
        yield Point((x, y))

