def __get_ssh_keys_id_or_fingerprint(ssh_keys, token, name):
    ssh_keys_id = list()
    for ssh_key in ssh_keys:
        if type(ssh_key) in [int, type(2 ** 64)]:
            ssh_keys_id.append(int(ssh_key))
        elif type(ssh_key) == SSHKey:
            ssh_keys_id.append(ssh_key.id)
        elif type(ssh_key) in [type(u''), type('')]:
            regexp_of_fingerprint = '([0-9a-fA-F]{2}:){15}[0-9a-fA-F]'
            match = re.match(regexp_of_fingerprint, ssh_key)
            if match is not None and match.end() == len(ssh_key) - 1:
                ssh_keys_id.append(ssh_key)
            else:
                key = SSHKey()
                key.token = token
                results = key.load_by_pub_key(ssh_key)
                if results is None:
                    key.public_key = ssh_key
                    key.name = 'SSH Key %s' % name
                    key.create()
                else:
                    key = results
                ssh_keys_id.append(key.id)
        else:
            raise BadSSHKeyFormat('Droplet.ssh_keys should be a list of IDs, public keys' + ' or fingerprints.')
    return ssh_keys_id

def require_at_least_one_query_parameter(*query_parameter_names):

    def outer_wrapper(view):

        @wraps(view)
        def wrapper(request, *args, **kwargs):
            requirement_satisfied = False
            for query_parameter_name in query_parameter_names:
                query_parameter_values = request.query_params.getlist(query_parameter_name)
                kwargs[query_parameter_name] = query_parameter_values
                if query_parameter_values:
                    requirement_satisfied = True
            if not requirement_satisfied:
                raise ValidationError(detail='You must provide at least one of the following query parameters: {params}.'.format(params=', '.join(query_parameter_names)))
            return view(request, *args, **kwargs)
        return wrapper
    return outer_wrapper

def reusable(func):
    sig = signature(func)
    origin = func
    while hasattr(origin, '__wrapped__'):
        origin = origin.__wrapped__
    return type(origin.__name__, (ReusableGenerator,), dict([('__doc__', origin.__doc__), ('__module__', origin.__module__), ('__signature__', sig), ('__wrapped__', staticmethod(func))] + [(name, property(compose(itemgetter(name), attrgetter('_bound_args.arguments')))) for name in sig.parameters] + ([('__qualname__', origin.__qualname__)] if sys.version_info > (3,) else [])))

def get_requirements(requirements_file):
    lines = open(requirements_file).readlines()
    dependencies = []
    dependency_links = []
    for line in lines:
        package = line.strip()
        if package.startswith('#'):
            continue
        if any((package.startswith(prefix) for prefix in VCS_PREFIXES)):
            (package_link, __, package) = package.rpartition('#')
            package_link = re.sub('(.*)(?P<dependency_link>https?.*$)', '\\g<dependency_link>', package_link)
            package = re.sub('(egg=)?(?P<package_name>.*)==.*$', '\\g<package_name>', package)
            package_version = re.sub('.*[^=]==', '', line.strip())
            if package:
                dependency_links.append('{package_link}#egg={package}-{package_version}'.format(package_link=package_link, package=package, package_version=package_version))
        else:
            (package, __, __) = package.partition('#')
            package = package.strip()
        if package:
            dependencies.append(package)
    return (dependencies, dependency_links)

def wait_for_completion(self, response, timeout=3600, initial_wait=5, scaleup=10):
    if not response:
        return
    logger = logging.getLogger(__name__)
    wait_period = initial_wait
    next_increase = time.time() + wait_period * scaleup
    if timeout:
        timeout = time.time() + timeout
    while True:
        request = self.get_request(request_id=response['requestId'], status=True)
        if request['metadata']['status'] == 'DONE':
            break
        elif request['metadata']['status'] == 'FAILED':
            raise PBFailedRequest('Request {0} failed to complete: {1}'.format(response['requestId'], request['metadata']['message']), response['requestId'])
        current_time = time.time()
        if timeout and current_time > timeout:
            raise PBTimeoutError('Timed out waiting for request {0}.'.format(response['requestId']), response['requestId'])
        if current_time > next_increase:
            wait_period *= 2
            next_increase = time.time() + wait_period * scaleup
            scaleup *= 2
        logger.info("Request %s is in state '%s'. Sleeping for %i seconds...", response['requestId'], request['metadata']['status'], wait_period)
        time.sleep(wait_period)

