def stiel_thodos_dense(T, MW, Tc, Pc, Vc, Zc, Vm, kg):
    gamma = 210 * (Tc * MW ** 3.0 / (Pc / 100000.0) ** 4) ** (1 / 6.0)
    rhor = Vc / Vm
    if rhor < 0.5:
        term = 0.0122 * (exp(0.535 * rhor) - 1.0)
    elif rhor < 2:
        term = 0.0114 * (exp(0.67 * rhor) - 1.069)
    else:
        term = 0.0026 * (exp(1.155 * rhor) + 2.016)
    diff = term / Zc ** 5 / gamma
    kg = kg + diff
    return kg

def match_query(string, query):
    if six.callable(query):
        return query(string)
    elif isinstance(query, six.string_types) and isinstance(string, six.string_types):
        return re.match(query, string) is not None
    else:
        return query == string

def _VKtoSC(key: int) -> int:
    if key in _SCKeys:
        return _SCKeys[key]
    scanCode = ctypes.windll.user32.MapVirtualKeyA(key, 0)
    if not scanCode:
        return 0
    keyList = [Keys.VK_APPS, Keys.VK_CANCEL, Keys.VK_SNAPSHOT, Keys.VK_DIVIDE, Keys.VK_NUMLOCK]
    if key in keyList:
        scanCode |= 256
    return scanCode

