def make_lclist(basedir, outfile, use_list_of_filenames=None, lcformat='hat-sql', lcformatdir=None, fileglob=None, recursive=True, columns=['objectid', 'objectinfo.ra', 'objectinfo.decl', 'objectinfo.ndet'], makecoordindex=('objectinfo.ra', 'objectinfo.decl'), field_fitsfile=None, field_wcsfrom=None, field_scale=ZScaleInterval(), field_stretch=LinearStretch(), field_colormap=plt.cm.gray_r, field_findersize=None, field_pltopts={'marker': 'o', 'markersize': 10.0, 'markerfacecolor': 'none', 'markeredgewidth': 2.0, 'markeredgecolor': 'red'}, field_grid=False, field_gridcolor='k', field_zoomcontain=True, maxlcs=None, nworkers=NCPUS):
    try:
        formatinfo = get_lcformat(lcformat, use_lcformat_dir=lcformatdir)
        if formatinfo:
            (dfileglob, readerfunc, dtimecols, dmagcols, derrcols, magsarefluxes, normfunc) = formatinfo
        else:
            LOGERROR("can't figure out the light curve format")
            return None
    except Exception as e:
        LOGEXCEPTION("can't figure out the light curve format")
        return None
    if not fileglob:
        fileglob = dfileglob
    lcndetkey = dmagcols
    if isinstance(use_list_of_filenames, list):
        matching = use_list_of_filenames
    elif isinstance(basedir, list):
        matching = []
        for bdir in basedir:
            LOGINFO('searching for %s light curves in %s ...' % (lcformat, bdir))
            if recursive is False:
                matching.extend(glob.glob(os.path.join(bdir, fileglob)))
            elif sys.version_info[:2] > (3, 4):
                matching.extend(glob.glob(os.path.join(bdir, '**', fileglob), recursive=True))
            else:
                walker = os.walk(bdir)
                for (root, dirs, _files) in walker:
                    for sdir in dirs:
                        searchpath = os.path.join(root, sdir, fileglob)
                        foundfiles = glob.glob(searchpath)
                        if foundfiles:
                            matching.extend(foundfiles)
    else:
        LOGINFO('searching for %s light curves in %s ...' % (lcformat, basedir))
        if recursive is False:
            matching = glob.glob(os.path.join(basedir, fileglob))
        elif sys.version_info[:2] > (3, 4):
            matching = glob.glob(os.path.join(basedir, '**', fileglob), recursive=True)
        else:
            walker = os.walk(basedir)
            matching = []
            for (root, dirs, _files) in walker:
                for sdir in dirs:
                    searchpath = os.path.join(root, sdir, fileglob)
                    foundfiles = glob.glob(searchpath)
                    if foundfiles:
                        matching.extend(foundfiles)
    if matching and len(matching) > 0:
        LOGINFO('found %s light curves' % len(matching))
        if maxlcs:
            matching = matching[:maxlcs]
        lclistdict = {'basedir': basedir, 'lcformat': lcformat, 'fileglob': fileglob, 'recursive': recursive, 'columns': columns, 'makecoordindex': makecoordindex, 'nfiles': len(matching), 'objects': {}}
        derefcols = ['lcfname']
        derefcols.extend(['%s.ndet' % x.split('.')[-1] for x in lcndetkey])
        for dc in derefcols:
            lclistdict['objects'][dc] = []
        for col in columns:
            thiscol = col.split('.')
            thiscol = thiscol[-1]
            lclistdict['objects'][thiscol] = []
            derefcols.append(thiscol)
        LOGINFO('collecting light curve info...')
        tasks = [(x, columns, lcformat, lcformatdir, lcndetkey) for x in matching]
        with ProcessPoolExecutor(max_workers=nworkers) as executor:
            results = executor.map(_lclist_parallel_worker, tasks)
        results = [x for x in results]
        for result in results:
            for xcol in derefcols:
                lclistdict['objects'][xcol].append(result[xcol])
        executor.shutdown()
        for col in lclistdict['objects']:
            lclistdict['objects'][col] = np.array(lclistdict['objects'][col])
        (uniques, counts) = np.unique(lclistdict['objects']['objectid'], return_counts=True)
        duplicated_objectids = uniques[counts > 1]
        if duplicated_objectids.size > 0:
            dt = lclistdict['objects']['objectid'].dtype.str
            dt = '<U%s' % (int(dt.replace('<', '').replace('U', '').replace('S', '')) + 3)
            lclistdict['objects']['objectid'] = np.array(lclistdict['objects']['objectid'], dtype=dt)
            for objid in duplicated_objectids:
                objid_inds = np.where(lclistdict['objects']['objectid'] == objid)
                for (ncounter, nind) in enumerate(objid_inds[0][1:]):
                    lclistdict['objects']['objectid'][nind] = '%s-%s' % (lclistdict['objects']['objectid'][nind], ncounter + 2)
                    LOGWARNING('tagging duplicated instance %s of objectid: %s as %s-%s, lightcurve: %s' % (ncounter + 2, objid, objid, ncounter + 2, lclistdict['objects']['lcfname'][nind]))
        if makecoordindex and isinstance(makecoordindex, (list, tuple)) and (len(makecoordindex) == 2):
            try:
                (racol, declcol) = makecoordindex
                racol = racol.split('.')[-1]
                declcol = declcol.split('.')[-1]
                (objra, objdecl) = (lclistdict['objects'][racol], lclistdict['objects'][declcol])
                cosdecl = np.cos(np.radians(objdecl))
                sindecl = np.sin(np.radians(objdecl))
                cosra = np.cos(np.radians(objra))
                sinra = np.sin(np.radians(objra))
                xyz = np.column_stack((cosra * cosdecl, sinra * cosdecl, sindecl))
                kdt = sps.cKDTree(xyz, copy_data=True)
                lclistdict['kdtree'] = kdt
                LOGINFO('kdtree generated for (ra, decl): (%s, %s)' % (makecoordindex[0], makecoordindex[1]))
            except Exception as e:
                LOGEXCEPTION('could not make kdtree for (ra, decl): (%s, %s)' % (makecoordindex[0], makecoordindex[1]))
                raise
        if field_fitsfile and os.path.exists(field_fitsfile):
            if field_wcsfrom is None:
                hdulist = pyfits.open(field_fitsfile)
                hdr = hdulist[0].header
                hdulist.close()
                w = WCS(hdr)
                wcsok = True
            elif os.path.exists(field_wcsfrom):
                w = WCS(field_wcsfrom)
                wcsok = True
            else:
                LOGERROR('could not determine WCS info for input FITS: %s' % field_fitsfile)
                wcsok = False
            if wcsok:
                radecl = np.column_stack((objra, objdecl))
                lclistdict['objects']['framexy'] = w.all_world2pix(radecl, 1)
                finder_outfile = os.path.join(os.path.dirname(outfile), os.path.splitext(os.path.basename(outfile))[0] + '.png')
                finder_png = fits_finder_chart(field_fitsfile, finder_outfile, wcsfrom=field_wcsfrom, scale=field_scale, stretch=field_stretch, colormap=field_colormap, findersize=field_findersize, overlay_ra=objra, overlay_decl=objdecl, overlay_pltopts=field_pltopts, overlay_zoomcontain=field_zoomcontain, grid=field_grid, gridcolor=field_gridcolor)
                if finder_png is not None:
                    LOGINFO('generated a finder PNG with an object position overlay for this LC list: %s' % finder_png)
        with open(outfile, 'wb') as outfd:
            pickle.dump(lclistdict, outfd, protocol=pickle.HIGHEST_PROTOCOL)
        LOGINFO('done. LC info -> %s' % outfile)
        return outfile
    else:
        LOGERROR('no files found in %s matching %s' % (basedir, fileglob))
        return None

