def aggregate_tree(l_tree):

    def _aggregate_phase1(tree):
        n_tree = radix.Radix()
        for prefix in tree.prefixes():
            if tree.search_worst(prefix).prefix == prefix:
                n_tree.add(prefix)
        return n_tree

    def _aggregate_phase2(tree):
        n_tree = radix.Radix()
        for rnode in tree:
            p = text(ip_network(text(rnode.prefix)).supernet())
            r = tree.search_covered(p)
            if len(r) == 2:
                if r[0].prefixlen == r[1].prefixlen == rnode.prefixlen:
                    n_tree.add(p)
                else:
                    n_tree.add(rnode.prefix)
            else:
                n_tree.add(rnode.prefix)
        return n_tree
    l_tree = _aggregate_phase1(l_tree)
    if len(l_tree.prefixes()) == 1:
        return l_tree
    while True:
        r_tree = _aggregate_phase2(l_tree)
        if l_tree.prefixes() == r_tree.prefixes():
            break
        else:
            l_tree = r_tree
            del r_tree
    return l_tree

def getNotesForABF(abfFile):
    parent = getParent(abfFile)
    parent = os.path.basename(parent).replace('.abf', '')
    expFile = os.path.dirname(abfFile) + '/experiment.txt'
    if not os.path.exists(expFile):
        return 'no experiment file'
    with open(expFile) as f:
        raw = f.readlines()
    for line in raw:
        if line[0] == '~':
            line = line[1:].strip()
            if line.startswith(parent):
                while '\t\t' in line:
                    line = line.replace('\t\t', '\t')
                line = line.replace('\t', '\n')
                return line
    return "experiment.txt found, but didn't contain %s" % parent

