def macf_period_find(times, mags, errs, fillgaps=0.0, filterwindow=11, forcetimebin=None, maxlags=None, maxacfpeaks=10, smoothacf=21, smoothfunc=_smooth_acf_savgol, smoothfunckwargs=None, magsarefluxes=False, sigclip=3.0, verbose=True, periodepsilon=0.1, nworkers=None, startp=None, endp=None, autofreq=None, stepsize=None):
    acfres = autocorr_magseries(times, mags, errs, maxlags=maxlags, fillgaps=fillgaps, forcetimebin=forcetimebin, sigclip=sigclip, magsarefluxes=magsarefluxes, filterwindow=filterwindow, verbose=verbose)
    xlags = acfres['lags']
    if smoothacf and isinstance(smoothacf, int) and (smoothacf > 0):
        if smoothfunckwargs is None:
            sfkwargs = {'windowsize': smoothacf}
        else:
            sfkwargs = smoothfunckwargs.copy()
            sfkwargs.update({'windowsize': smoothacf})
        xacf = smoothfunc(acfres['acf'], **sfkwargs)
    else:
        xacf = acfres['acf']
    peakres = _get_acf_peakheights(xlags, xacf, npeaks=maxacfpeaks, searchinterval=int(smoothacf / 2))
    bestlspval = peakres['bestpeakheight']
    try:
        fity = npconcatenate(([0.0, peakres['bestlag']], peakres['relpeaklags'][peakres['relpeaklags'] > peakres['bestlag']]))
        fity = fity * acfres['cadence']
        fitx = nparange(fity.size)
        (fitcoeffs, fitcovar) = nppolyfit(fitx, fity, 1, cov=True)
        fitbestperiod = fitcoeffs[0]
        bestperiodrms = npsqrt(fitcovar[0, 0])
    except Exception as e:
        LOGWARNING('linear fit to time at each peak lag value vs. peak number failed, naively calculated ACF period may not be accurate')
        fitcoeffs = nparray([npnan, npnan])
        fitcovar = nparray([[npnan, npnan], [npnan, npnan]])
        fitbestperiod = npnan
        bestperiodrms = npnan
        raise
    naivebestperiod = peakres['bestlag'] * acfres['cadence']
    if fitbestperiod < naivebestperiod:
        LOGWARNING('fit bestperiod = %.5f may be an alias, naively calculated bestperiod is = %.5f' % (fitbestperiod, naivebestperiod))
    if npisfinite(fitbestperiod):
        bestperiod = fitbestperiod
    else:
        bestperiod = naivebestperiod
    return {'bestperiod': bestperiod, 'bestlspval': bestlspval, 'nbestpeaks': maxacfpeaks, 'nbestperiods': npconcatenate([[fitbestperiod], peakres['relpeaklags'][1:maxacfpeaks] * acfres['cadence']]), 'nbestlspvals': peakres['maxacfs'][:maxacfpeaks], 'lspvals': xacf, 'periods': xlags * acfres['cadence'], 'acf': xacf, 'lags': xlags, 'method': 'acf', 'naivebestperiod': naivebestperiod, 'fitbestperiod': fitbestperiod, 'fitperiodrms': bestperiodrms, 'periodfitcoeffs': fitcoeffs, 'periodfitcovar': fitcovar, 'kwargs': {'maxlags': maxlags, 'maxacfpeaks': maxacfpeaks, 'fillgaps': fillgaps, 'filterwindow': filterwindow, 'smoothacf': smoothacf, 'smoothfunckwargs': sfkwargs, 'magsarefluxes': magsarefluxes, 'sigclip': sigclip}, 'acfresults': acfres, 'acfpeaks': peakres}

