def make_ec2_nodes(security_groupid, subnet_id, keypair_name, iam_instance_profile_arn, launch_instances=1, ami='ami-04681a1dbd79675a5', instance='t3.micro', ebs_optimized=True, user_data=None, wait_until_up=True, client=None, raiseonfail=False):
    if not client:
        client = boto3.client('ec2')
    if isinstance(user_data, str) and os.path.exists(user_data):
        with open(user_data, 'r') as infd:
            udata = infd.read()
    elif isinstance(user_data, str):
        udata = user_data
    else:
        udata = '#!/bin/bash\necho "No user data provided. Launched instance at: %s UTC"' % datetime.utcnow().isoformat()
    try:
        resp = client.run_instances(ImageId=ami, InstanceType=instance, SecurityGroupIds=[security_groupid], SubnetId=subnet_id, UserData=udata, IamInstanceProfile={'Arn': iam_instance_profile_arn}, InstanceInitiatedShutdownBehavior='terminate', KeyName=keypair_name, MaxCount=launch_instances, MinCount=launch_instances, EbsOptimized=ebs_optimized)
        if not resp:
            LOGERROR('could not launch requested instance')
            return None
        else:
            instance_dict = {}
            instance_list = resp.get('Instances', [])
            if len(instance_list) > 0:
                for instance in instance_list:
                    LOGINFO('launched instance ID: %s of type: %s at: %s. current state: %s' % (instance['InstanceId'], instance['InstanceType'], instance['LaunchTime'].isoformat(), instance['State']['Name']))
                    instance_dict[instance['InstanceId']] = {'type': instance['InstanceType'], 'launched': instance['LaunchTime'], 'state': instance['State']['Name'], 'info': instance}
            if wait_until_up:
                ready_instances = []
                LOGINFO('waiting until launched instances are up...')
                ntries = 5
                curr_try = 0
                while curr_try < ntries or len(ready_instances) < len(list(instance_dict.keys())):
                    resp = client.describe_instances(InstanceIds=list(instance_dict.keys()))
                    if len(resp['Reservations']) > 0:
                        for resv in resp['Reservations']:
                            if len(resv['Instances']) > 0:
                                for instance in resv['Instances']:
                                    if instance['State']['Name'] == 'running':
                                        ready_instances.append(instance['InstanceId'])
                                        instance_dict[instance['InstanceId']]['state'] = 'running'
                                        instance_dict[instance['InstanceId']]['ip'] = instance['PublicIpAddress']
                                        instance_dict[instance['InstanceId']]['info'] = instance
                    curr_try = curr_try + 1
                    time.sleep(5.0)
                if len(ready_instances) == len(list(instance_dict.keys())):
                    LOGINFO('all instances now up.')
                else:
                    LOGWARNING('reached maximum number of tries for instance status, not all instances may be up.')
            return instance_dict
    except ClientError as e:
        LOGEXCEPTION('could not launch requested instance')
        if raiseonfail:
            raise
        return None
    except Exception as e:
        LOGEXCEPTION('could not launch requested instance')
        if raiseonfail:
            raise
        return None

def UpdatePreprocessor(self, line):
    if Match('^\\s*#\\s*(if|ifdef|ifndef)\\b', line):
        self.pp_stack.append(_PreprocessorInfo(copy.deepcopy(self.stack)))
    elif Match('^\\s*#\\s*(else|elif)\\b', line):
        if self.pp_stack:
            if not self.pp_stack[-1].seen_else:
                self.pp_stack[-1].seen_else = True
                self.pp_stack[-1].stack_before_else = copy.deepcopy(self.stack)
            self.stack = copy.deepcopy(self.pp_stack[-1].stack_before_if)
        else:
            pass
    elif Match('^\\s*#\\s*endif\\b', line):
        if self.pp_stack:
            if self.pp_stack[-1].seen_else:
                self.stack = self.pp_stack[-1].stack_before_else
            self.pp_stack.pop()
        else:
            pass

