def pbkdf2_iteration_calculator(hash_algorithm, key_length, target_ms=100, quiet=False):
    if hash_algorithm not in set(['sha1', 'sha224', 'sha256', 'sha384', 'sha512']):
        raise ValueError(pretty_message('\n            hash_algorithm must be one of "sha1", "sha224", "sha256", "sha384",\n            "sha512", not %s\n            ', repr(hash_algorithm)))
    if not isinstance(key_length, int_types):
        raise TypeError(pretty_message('\n            key_length must be an integer, not %s\n            ', type_name(key_length)))
    if key_length < 1:
        raise ValueError(pretty_message('\n            key_length must be greater than 0 - is %s\n            ', repr(key_length)))
    if not isinstance(target_ms, int_types):
        raise TypeError(pretty_message('\n            target_ms must be an integer, not %s\n            ', type_name(target_ms)))
    if target_ms < 1:
        raise ValueError(pretty_message('\n            target_ms must be greater than 0 - is %s\n            ', repr(target_ms)))
    if pbkdf2.pure_python:
        raise OSError(pretty_message('\n            Only a very slow, pure-python version of PBKDF2 is available,\n            making this function useless\n            '))
    iterations = 10000
    password = 'this is a test'.encode('utf-8')
    salt = rand_bytes(key_length)

    def _measure():
        start = _get_start()
        pbkdf2(hash_algorithm, password, salt, iterations, key_length)
        observed_ms = _get_elapsed(start)
        if not quiet:
            print('%s iterations in %sms' % (iterations, observed_ms))
        return 1.0 / target_ms * observed_ms
    fraction = _measure()
    iterations = int(iterations / fraction / 2.0)
    fraction = _measure()
    iterations = iterations / fraction
    round_factor = -3 if iterations < 100000 else -4
    result = int(round(iterations, round_factor))
    if result > 20000:
        result = result // 5000 * 5000
    return result

