def prepare_upload_bundle(name, data):
    (fd, path) = mkstemp()
    zip_file = ZipFile(path, 'w')
    for (ext, stream) in data.items():
        fname = '%s.%s' % (name, ext)
        if isinstance(stream, basestring):
            zip_file.write(stream, fname)
        else:
            zip_file.writestr(fname, stream.read())
    zip_file.close()
    os.close(fd)
    return path

