def run(data, samples, noreverse, maxindels, force, ipyclient):
    subsamples = []
    for sample in samples:
        if sample.stats.state < 2:
            print('    Sample not ready for clustering. First run step2 on sample: {}'.format(sample.name))
            continue
        if not force:
            if sample.stats.state >= 3:
                print('    Skipping {}; aleady clustered. Use force to re-cluster'.format(sample.name))
            elif sample.stats.reads_passed_filter:
                subsamples.append(sample)
        elif sample.stats.reads_passed_filter:
            subsamples.append(sample)
    if not subsamples:
        print('  No Samples ready to be clustered. First run step2().')
    else:
        try:
            setup_dirs(data)
            if not data.paramsdict['assembly_method'] == 'denovo':
                for sample in subsamples:
                    refmap_init(data, sample, force)
                    nthreads = 2
            else:
                nthreads = 1
            if 'threads' in data._ipcluster.keys():
                nthreads = int(data._ipcluster['threads'])
                _ncpus = len(ipyclient)
                if _ncpus > 2 * len(data.samples):
                    nthreads *= 2
            args = [data, subsamples, ipyclient, nthreads, maxindels, force]
            new_apply_jobs(*args)
        finally:
            try:
                log_level = logging.getLevelName(LOGGER.getEffectiveLevel())
                if not log_level == 'DEBUG':
                    if os.path.exists(data.tmpdir):
                        shutil.rmtree(data.tmpdir)
                    rdereps = glob.glob(os.path.join(data.dirs.edits, '*-refmap_derep.fastq'))
                    for rmfile in rdereps:
                        os.remove(rmfile)
            except Exception as _:
                LOGGER.warning('failed to cleanup files/dirs')

def run(command, parser, cl_args, unknown_args):
    Log.debug('Submit Args %s', cl_args)
    topology_file = cl_args['topology-file-name']
    if urlparse.urlparse(topology_file).scheme:
        cl_args['topology-file-name'] = download(topology_file, cl_args['cluster'])
        topology_file = cl_args['topology-file-name']
        Log.debug('download uri to local file: %s', topology_file)
    if not os.path.isfile(topology_file):
        err_context = "Topology file '%s' does not exist" % topology_file
        return SimpleResult(Status.InvocationError, err_context)
    jar_type = topology_file.endswith('.jar')
    tar_type = topology_file.endswith('.tar') or topology_file.endswith('.tar.gz')
    pex_type = topology_file.endswith('.pex')
    cpp_type = topology_file.endswith('.dylib') or topology_file.endswith('.so')
    if not (jar_type or tar_type or pex_type or cpp_type):
        (_, ext_name) = os.path.splitext(topology_file)
        err_context = "Unknown file type '%s'. Please use .tar or .tar.gz or .jar or .pex or .dylib or .so file" % ext_name
        return SimpleResult(Status.InvocationError, err_context)
    if cl_args['extra_launch_classpath']:
        valid_classpath = classpath.valid_java_classpath(cl_args['extra_launch_classpath'])
        if not valid_classpath:
            err_context = 'One of jar or directory in extra launch classpath does not exist: %s' % cl_args['extra_launch_classpath']
            return SimpleResult(Status.InvocationError, err_context)
    tmp_dir = tempfile.mkdtemp()
    opts.cleaned_up_files.append(tmp_dir)
    if cl_args['deploy_deactivated']:
        initial_state = topology_pb2.TopologyState.Name(topology_pb2.PAUSED)
    else:
        initial_state = topology_pb2.TopologyState.Name(topology_pb2.RUNNING)
    opts.set_config('cmdline.topologydefn.tmpdirectory', tmp_dir)
    opts.set_config('cmdline.topology.initial.state', initial_state)
    opts.set_config('cmdline.topology.role', cl_args['role'])
    opts.set_config('cmdline.topology.environment', cl_args['environ'])
    if not cl_args['release_yaml_file']:
        cl_args['release_yaml_file'] = config.get_heron_release_file()
    if jar_type:
        return submit_fatjar(cl_args, unknown_args, tmp_dir)
    elif tar_type:
        return submit_tar(cl_args, unknown_args, tmp_dir)
    elif cpp_type:
        return submit_cpp(cl_args, unknown_args, tmp_dir)
    else:
        return submit_pex(cl_args, unknown_args, tmp_dir)

def save(self, description=None, raiseError=True, ntrials=3):
    assert isinstance(raiseError, bool), 'raiseError must be boolean'
    assert isinstance(ntrials, int), 'ntrials must be integer'
    assert ntrials > 0, 'ntrials must be >0'
    if description is not None:
        assert isinstance(description, basestring), 'description must be None or a string'
    dirInfoPath = os.path.join(self.__path, self.__dirInfo)
    if description is None and (not os.path.isfile(dirInfoPath)):
        description = ''
    LR = Locker(filePath=None, lockPass=str(uuid.uuid1()), lockPath=os.path.join(self.__path, self.__repoLock))
    (acquired, code) = LR.acquire_lock()
    m = "code %s. Unable to aquire the lock when calling 'save'. You may try again!" % (code,)
    if not acquired:
        assert not raiseError, Exception(m)
        return (False, m)
    for _trial in range(ntrials):
        try:
            repoInfoPath = os.path.join(self.__path, self.__repoFile)
            error = None
            self.__save_dirinfo(description=description, dirInfoPath=dirInfoPath)
            if os.path.isfile(repoInfoPath):
                with open(repoInfoPath, 'rb') as fd:
                    repo = self.__load_repository_pickle_file(os.path.join(self.__path, self.__repoFile))
                    self.__repo['walk_repo'] = repo['walk_repo']
            with open(repoInfoPath, 'wb') as fd:
                self.__repo['last_update_utctime'] = time.time()
                pickle.dump(self.__repo, fd, protocol=self._DEFAULT_PICKLE_PROTOCOL)
                fd.flush()
                os.fsync(fd.fileno())
        except Exception as err:
            error = 'Unable to save repository (%s)' % err
            if self.DEBUG_PRINT_FAILED_TRIALS:
                print('Trial %i failed in Repository.%s (%s). Set Repository.DEBUG_PRINT_FAILED_TRIALS to False to mute' % (_trial, inspect.stack()[1][3], str(error)))
        else:
            break
    LR.release_lock()
    assert error is None or not raiseError, error
    return (error is None, error)

