def CheckCheck(filename, clean_lines, linenum, error):
    lines = clean_lines.elided
    (check_macro, start_pos) = FindCheckMacro(lines[linenum])
    if not check_macro:
        return
    (last_line, end_line, end_pos) = CloseExpression(clean_lines, linenum, start_pos)
    if end_pos < 0:
        return
    if not Match('\\s*;', last_line[end_pos:]):
        return
    if linenum == end_line:
        expression = lines[linenum][start_pos + 1:end_pos - 1]
    else:
        expression = lines[linenum][start_pos + 1:]
        for i in xrange(linenum + 1, end_line):
            expression += lines[i]
        expression += last_line[0:end_pos - 1]
    lhs = ''
    rhs = ''
    operator = None
    while expression:
        matched = Match('^\\s*(<<|<<=|>>|>>=|->\\*|->|&&|\\|\\||==|!=|>=|>|<=|<|\\()(.*)$', expression)
        if matched:
            token = matched.group(1)
            if token == '(':
                expression = matched.group(2)
                (end, _) = FindEndOfExpressionInLine(expression, 0, ['('])
                if end < 0:
                    return
                lhs += '(' + expression[0:end]
                expression = expression[end:]
            elif token in ('&&', '||'):
                return
            elif token in ('<<', '<<=', '>>', '>>=', '->*', '->'):
                lhs += token
                expression = matched.group(2)
            else:
                operator = token
                rhs = matched.group(2)
                break
        else:
            matched = Match('^([^-=!<>()&|]+)(.*)$', expression)
            if not matched:
                matched = Match('^(\\s*\\S)(.*)$', expression)
                if not matched:
                    break
            lhs += matched.group(1)
            expression = matched.group(2)
    if not (lhs and operator and rhs):
        return
    if rhs.find('&&') > -1 or rhs.find('||') > -1:
        return
    lhs = lhs.strip()
    rhs = rhs.strip()
    match_constant = '^([-+]?(\\d+|0[xX][0-9a-fA-F]+)[lLuU]{0,3}|".*"|\\\'.*\\\')$'
    if Match(match_constant, lhs) or Match(match_constant, rhs):
        error(filename, linenum, 'readability/check', 2, 'Consider using %s instead of %s(a %s b)' % (_CHECK_REPLACEMENT[check_macro][operator], check_macro, operator))

def extract_rets_pos_txn_from_zipline(backtest):
    backtest.index = backtest.index.normalize()
    if backtest.index.tzinfo is None:
        backtest.index = backtest.index.tz_localize('UTC')
    returns = backtest.returns
    raw_positions = []
    for (dt, pos_row) in backtest.positions.iteritems():
        df = pd.DataFrame(pos_row)
        df.index = [dt] * len(df)
        raw_positions.append(df)
    if not raw_positions:
        raise ValueError('The backtest does not have any positions.')
    positions = pd.concat(raw_positions)
    positions = pos.extract_pos(positions, backtest.ending_cash)
    transactions = txn.make_transaction_frame(backtest.transactions)
    if transactions.index.tzinfo is None:
        transactions.index = transactions.index.tz_localize('utc')
    return (returns, positions, transactions)

