def compute(slidingWindow, total, newVal, windowSize):
    if len(slidingWindow) == windowSize:
        total -= slidingWindow.pop(0)
    slidingWindow.append(newVal)
    total += newVal
    return (float(total) / len(slidingWindow), slidingWindow, total)

