def get_epochs_given_midtimes_and_period(t_mid, period, err_t_mid=None, t0_fixed=None, t0_percentile=None, verbose=False):
    kwargarr = np.array([isinstance(err_t_mid, np.ndarray), t0_fixed, t0_percentile])
    if not _single_true(kwargarr) and (not np.all(~kwargarr.astype(bool))):
        raise AssertionError('can have at most one of err_t_mid, t0_fixed, t0_percentile')
    t_mid = t_mid[np.isfinite(t_mid)]
    N_midtimes = len(t_mid)
    if t0_fixed:
        t0 = t0_fixed
    elif isinstance(err_t_mid, np.ndarray):
        t0_avg = np.average(t_mid, weights=1 / err_t_mid ** 2)
        t0_options = np.arange(min(t_mid), max(t_mid) + period, period)
        t0 = t0_options[np.argmin(np.abs(t0_options - t0_avg))]
    elif not t0_percentile:
        if N_midtimes % 2 == 1:
            t0 = np.median(t_mid)
        else:
            t0 = t_mid[int(N_midtimes / 2)]
    else:
        t0 = np.sort(t_mid)[int(N_midtimes * t0_percentile / 100)]
    epoch = (t_mid - t0) / period
    int_epoch = np.round(epoch, 0)
    if verbose:
        LOGINFO('epochs before rounding')
        LOGINFO('\n{:s}'.format(repr(epoch)))
        LOGINFO('epochs after rounding')
        LOGINFO('\n{:s}'.format(repr(int_epoch)))
    return (int_epoch, t0)

def configure_devel_job(config_url, rosdistro_name, source_build_name, repo_name, os_name, os_code_name, arch, pull_request=False, config=None, build_file=None, index=None, dist_file=None, dist_cache=None, jenkins=None, views=None, is_disabled=False, groovy_script=None, source_repository=None, build_targets=None, dry_run=False):
