            m_version = u' ' + RESET + BRIGHT + RED + u'missing' + RESET
        else:
            m_version = DIM + u'@%s' % m.version
        if not latest_v:
            print(u'%s%s%s%s not available from the registry%s' % (RED, name, m_version, NORMAL, RESET))
            status = 2
            continue
        elif not m or m.version < latest_v:
            update_prevented_by = ''
            if m:
                specs_preventing_update = [x for x in dependency_specs if x.name == name and (not sourceparse.parseSourceURL(x.nonShrinkwrappedVersionReq()).semanticSpecMatches(latest_v))]
                shrinkwrap_prevents_update = [x for x in dependency_specs if x.name == name and x.isShrinkwrapped() and (not sourceparse.parseSourceURL(x.versionReq()).semanticSpecMatches(latest_v))]
                if len(specs_preventing_update):
                    update_prevented_by = ' (update prevented by specifications: %s)' % ', '.join(['%s from %s' % (x.version_req, x.specifying_module) for x in specs_preventing_update])
                if len(shrinkwrap_prevents_update):
                    update_prevented_by += ' yotta-shrinkwrap.json prevents update'
                if m.version.major() < latest_v.major():
                    colour = GREEN
                elif m.version.minor() < latest_v.minor():
                    colour = YELLOW
                else:
                    colour = RED
            else:
                colour = RED
            print(u'%s%s%s latest: %s%s%s%s' % (name, m_version, RESET, colour, latest_v.version, update_prevented_by, RESET))
            if not status:
                status = 1
    return status

