def prevweekday(when, weekday, inclusive=True):
    if isinstance(when, datetime):
        when = when.date()
    delta = weekday - when.weekday()
    if inclusive and delta > 0 or (not inclusive and delta >= 0):
        delta -= 7
    return when + timedelta(days=delta)

