    try:
        (_, protocol) = await loop.create_connection(lambda : QTMProtocol(loop=loop, on_event=on_event, on_disconnect=on_disconnect), host, port)
    except (ConnectionRefusedError, TimeoutError, OSError) as exception:
        LOG.error(exception)
        return None
    try:
        await protocol.set_version(version)
    except QRTCommandException as exception:
        LOG.error(Exception)
        return None
    except TypeError as exception:
        LOG.error(exception)
        return None
    return QRTConnection(protocol, timeout=timeout)

