def encode(self, word, max_length=4, var='American', reverse=False, zero_pad=True):
    if max_length != -1:
        max_length = min(max(4, max_length), 64)
    else:
        max_length = 64
    word = unicode_normalize('NFKD', text_type(word.upper()))
    word = word.replace('ß', 'SS')
    if var == 'Census':
        if word[:3] in {'VAN', 'CON'} and len(word) > 4:
            return (soundex(word, max_length, 'American', reverse, zero_pad), soundex(word[3:], max_length, 'American', reverse, zero_pad))
        if word[:2] in {'DE', 'DI', 'LA', 'LE'} and len(word) > 3:
            return (soundex(word, max_length, 'American', reverse, zero_pad), soundex(word[2:], max_length, 'American', reverse, zero_pad))
    word = ''.join((c for c in word if c in self._uc_set))
    if not word:
        if zero_pad:
            return '0' * max_length
        return '0'
    if reverse:
        word = word[::-1]
    sdx = word.translate(self._trans)
    if var == 'special':
        sdx = sdx.replace('9', '0')
    else:
        sdx = sdx.replace('9', '')
    sdx = self._delete_consecutive_repeats(sdx)
    if word[0] in 'HW':
        sdx = word[0] + sdx
    else:
        sdx = word[0] + sdx[1:]
    sdx = sdx.replace('0', '')
    if zero_pad:
        sdx += '0' * max_length
    return sdx[:max_length]

