    for obj in args:
        if isinstance(obj, numbers.Number):
            obj = str(obj)
        if isinstance(obj, basestring):
            obj = escape(obj)
            self.children.append(obj)
        elif isinstance(obj, dom_tag):
            ctx = dom_tag._with_contexts[_get_thread_context()]
            if ctx and ctx[-1]:
                ctx[-1].used.add(obj)
            self.children.append(obj)
            obj.parent = self
            obj.setdocument(self.document)
        elif isinstance(obj, dict):
            for (attr, value) in obj.items():
                self.set_attribute(*dom_tag.clean_pair(attr, value))
        elif hasattr(obj, '__iter__'):
            for subobj in obj:
                self.add(subobj)
        else:
            raise ValueError('%r not a tag or string.' % obj)
    if len(args) == 1:
        return args[0]
    return args

def to_type_constructor(value, python_path=None):
    if not value:
        return value
    if callable(value):
        return {'datatype': value}
    value = to_type(value)
    typename = value.get('typename')
    if typename:
        r = aliases.resolve(typename)
        try:
            value['datatype'] = importer.import_symbol(r, python_path=python_path)
            del value['typename']
        except Exception as e:
            value['_exception'] = e
    return value

def hump_to_underscore(name):
    new_name = ''
    pos = 0
    for c in name:
        if pos == 0:
            new_name = c.lower()
        elif 65 <= ord(c) <= 90:
            new_name += '_' + c.lower()
            pass
        else:
            new_name += c
        pos += 1
        pass
    return new_name

