    def func(radius):
        radius = dim.Length(radius, unit_length=unit_length)
        return self.mass_within_circle_in_units(radius=radius) - np.pi * radius ** 2.0
    radius = self.ellipticity_rescale * root_scalar(func, bracket=[0.0001, 1000.0]).root
