def _update(obj, fields=None, save=False, overwrite=False):
    if not fields:
        meta = obj._meta
        fields = [f.name for f in meta.fields if not f.primary_key and hasattr(meta, '_get_' + f.name) and hasattr(meta, '_' + f.name)]
    fields_updated = []
    for field in fields:
        if not overwrite and (not getattr(obj, field, None) == None):
            continue
        if hasattr(obj, field):
            setattr(obj, field, getattr(obj, '_' + field, None))
            if getattr(obj, field, None) != None:
                fields_updated += [field]
    if save:
        obj.save()
    return fields_updated

def hash_data(data, hasher=NoParam, base=NoParam, types=False, hashlen=NoParam, convert=False):
    if convert and isinstance(data, six.string_types):
        try:
            data = json.dumps(data)
        except TypeError as ex:
            pass
    base = _rectify_base(base)
    hashlen = _rectify_hashlen(hashlen)
    hasher = _rectify_hasher(hasher)()
    _update_hasher(hasher, data, types=types)
    text = _digest_hasher(hasher, hashlen, base)
    return text

