def EQ127(T, A, B, C, D, E, F, G, order=0):
    if order == 0:
        return A + B * ((C / T) ** 2 * exp(C / T) / (exp(C / T) - 1) ** 2) + D * ((E / T) ** 2 * exp(E / T) / (exp(E / T) - 1) ** 2) + F * ((G / T) ** 2 * exp(G / T) / (exp(G / T) - 1) ** 2)
    elif order == 1:
        return -B * C ** 3 * exp(C / T) / (T ** 4 * (exp(C / T) - 1) ** 2) + 2 * B * C ** 3 * exp(2 * C / T) / (T ** 4 * (exp(C / T) - 1) ** 3) - 2 * B * C ** 2 * exp(C / T) / (T ** 3 * (exp(C / T) - 1) ** 2) - D * E ** 3 * exp(E / T) / (T ** 4 * (exp(E / T) - 1) ** 2) + 2 * D * E ** 3 * exp(2 * E / T) / (T ** 4 * (exp(E / T) - 1) ** 3) - 2 * D * E ** 2 * exp(E / T) / (T ** 3 * (exp(E / T) - 1) ** 2) - F * G ** 3 * exp(G / T) / (T ** 4 * (exp(G / T) - 1) ** 2) + 2 * F * G ** 3 * exp(2 * G / T) / (T ** 4 * (exp(G / T) - 1) ** 3) - 2 * F * G ** 2 * exp(G / T) / (T ** 3 * (exp(G / T) - 1) ** 2)
    elif order == -1:
        return A * T + B * C ** 2 / (C * exp(C / T) - C) + D * E ** 2 / (E * exp(E / T) - E) + F * G ** 2 / (G * exp(G / T) - G)
    elif order == -1j:
        return A * log(T) + B * C ** 2 * (1 / (C * T * exp(C / T) - C * T) + 1 / (C * T) - log(exp(C / T) - 1) / C ** 2) + D * E ** 2 * (1 / (E * T * exp(E / T) - E * T) + 1 / (E * T) - log(exp(E / T) - 1) / E ** 2) + F * G ** 2 * (1 / (G * T * exp(G / T) - G * T) + 1 / (G * T) - log(exp(G / T) - 1) / G ** 2)
    else:
        raise Exception(order_not_found_msg)

