def sys_access(self, buf, mode):
    filename = b''
    for i in range(0, 255):
        c = Operators.CHR(self.current.read_int(buf + i, 8))
        if c == b'\x00':
            break
        filename += c
    if os.access(filename, mode):
        return 0
    else:
        return -1

def play(args):
    if args[0].lower() != 'play':
        args.insert(0, 'play')
    else:
        args[0] = 'play'
    try:
        logger.info('Executing: %s', ' '.join(args))
        process_handle = subprocess.Popen(args, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
        status = process_handle.wait()
        if process_handle.stderr is not None:
            logger.info(process_handle.stderr)
        if status == 0:
            return True
        else:
            logger.info('Play returned with error code %s', status)
            return False
    except OSError as error_msg:
        logger.error('OSError: Play failed! %s', error_msg)
    except TypeError as error_msg:
        logger.error('TypeError: %s', error_msg)
    return False

def ensure_pandoc(func):
