    return np.expand_dims(blend, axis=-1)

def CHOLESKY(A, B, method='scipy'):
    if method == 'numpy_solver':
        X = _numpy_solver(A, B)
        return X
    elif method == 'numpy':
        (X, _L) = _numpy_cholesky(A, B)
        return X
    elif method == 'scipy':
        import scipy.linalg
        L = scipy.linalg.cholesky(A)
        X = scipy.linalg.cho_solve((L, False), B)
    else:
        raise ValueError('method must be numpy_solver, numpy_cholesky or cholesky_inplace')
    return X

def merge_from_list(self, list_args):

    def xs(name, parser_args, list_args):
        for (args, kwargs) in list_args:
            if len(set(args) & parser_args) > 0:
                yield (args, kwargs)
            elif 'dest' in kwargs:
                if kwargs['dest'] == name:
                    yield (args, kwargs)
    for (args, kwargs) in xs(self.name, self.parser_args, list_args):
        self.merge_args(args)
        self.merge_kwargs(kwargs)

def split(self, X, y=None, groups=None):
    (X, y, groups) = indexable(X, y, groups)
    cgrs = [~r for r in X]
    structure_condition = defaultdict(set)
    for (structure, condition) in zip(cgrs, groups):
        structure_condition[structure].add(condition)
    train_data = defaultdict(list)
    test_data = []
    for (n, (structure, condition)) in enumerate(zip(cgrs, groups)):
        train_data[condition].append(n)
        if len(structure_condition[structure]) > 1:
            test_data.append(n)
    for (condition, indexes) in train_data.items():
        test_index = [index for index in indexes if index in test_data]
        if test_index:
            train_index = [i for (cond, ind) in train_data.items() if cond != condition for i in ind]
            yield (array(train_index), array(test_index))

def depricated_name(newmethod):

    def decorator(func):

        @wraps(func)
        def wrapper(*args, **kwargs):
            warnings.simplefilter('always', DeprecationWarning)
            warnings.warn('Function {} is depricated, please use {} instead.'.format(func.__name__, newmethod), category=DeprecationWarning, stacklevel=2)
            warnings.simplefilter('default', DeprecationWarning)
            return func(*args, **kwargs)
        return wrapper
    return decorator

