            context.index = 0
        if hasattr(node, 'children'):
            mutate_list_of_nodes(node, context=context)
            if context.number_of_performed_mutations and context.mutation_id != ALL:
                return
        mutation = mutations_by_type.get(node.type)
        if mutation is None:
            return
        for (key, value) in sorted(mutation.items()):
            old = getattr(node, key)
            if context.exclude_line():
                continue
            new = evaluate(value, context=context, node=node, value=getattr(node, 'value', None), children=getattr(node, 'children', None))
            assert not callable(new)
            if new is not None and new != old:
                if context.should_mutate():
                    context.number_of_performed_mutations += 1
                    context.performed_mutation_ids.append(context.mutation_id_of_current_index)
                    setattr(node, key, new)
                context.index += 1
            if context.number_of_performed_mutations and context.mutation_id != ALL:
                return
    finally:
        context.stack.pop()

def _element2dict(self, parent):
    d = {}
    for node in parent.childNodes:
        if not isinstance(node, minidom.Element):
            continue
        if not node.hasChildNodes():
            continue
        if node.childNodes[0].nodeType == minidom.Node.ELEMENT_NODE:
            try:
                d[node.tagName]
            except KeyError:
                d[node.tagName] = []
            d[node.tagName].append(self._element2dict(node))
        elif len(node.childNodes) == 1 and node.childNodes[0].nodeType in [minidom.Node.CDATA_SECTION_NODE, minidom.Node.TEXT_NODE]:
            d[node.tagName] = node.childNodes[0].data
    return d

def average_node_annotation(graph: BELGraph, key: str, annotation: str='Subgraph', aggregator: Optional[Callable[[Iterable[X]], X]]=None) -> Mapping[str, X]:
    if aggregator is None:

        def aggregator(x):
            return sum(x) / len(x)
    result = {}
    for (subgraph, nodes) in group_nodes_by_annotation(graph, annotation).items():
        values = [graph.nodes[node][key] for node in nodes if key in graph.nodes[node]]
        result[subgraph] = aggregator(values)
    return result

def S_mag(self, T):
    tau = T / self.Tc_mag
    if tau <= 1.0:
        s = 1 - self._B_mag * (2 * tau ** 3 / 3 + 2 * tau ** 9 / 27 + 2 * tau ** 15 / 75) / self._D_mag
    else:
        s = (2 * tau ** (-5) / 5 + 2 * tau ** (-15) / 45 + 2 * tau ** (-25) / 125) / self._D_mag
    return -R * math.log(self.beta0_mag + 1) * s

