        _logger.debug('delete {}'.format(lock_string(lock)))
        if lock is None:
            return False
        key = 'URL2TOKEN:{}'.format(lock.get('root'))
        if key in self._dict:
            tokList = self._dict[key]
            if len(tokList) > 1:
                tokList.remove(token)
                self._dict[key] = tokList
            else:
                del self._dict[key]
        del self._dict[token]
        self._flush()
    finally:
        self._lock.release()
    return True

