def split_at_any(text, lis, translate=False, not_before=[], not_after=[], validitate=None):
    lis.sort(key=lambda x: len(x), reverse=True)
    last = 0
    n = 0
    text_len = len(text)
    while n < text_len:
        if any((text[:n].endswith(e) for e in not_before)):
            n += 1
            continue
        for e in lis:
            s = len(e)
            if s + n > text_len:
                continue
            if validitate and (not validitate(e, text[:n], text[n + s:])):
                continue
            if any((text[n + s:].startswith(e) for e in not_after)):
                n += 1
                break
            if e == text[n:n + s]:
                yield (text[last:n] if not translate else translate(text[last:n]))
                yield e
                n += s
                last = n
                break
        else:
            n += 1
    yield (text[last:n] if not translate else translate(text[last:n]))

def animate_phase_matrix(sync_output_dynamic, grid_width=None, grid_height=None, animation_velocity=75, colormap='jet', save_movie=None):
    figure = plt.figure()

    def init_frame():
        return frame_generation(0)

    def frame_generation(index_dynamic):
        figure.clf()
        axis = figure.add_subplot(111)
        phase_matrix = sync_output_dynamic.allocate_phase_matrix(grid_width, grid_height, index_dynamic)
        axis.imshow(phase_matrix, cmap=plt.get_cmap(colormap), interpolation='kaiser', vmin=0.0, vmax=2.0 * math.pi)
        artist = figure.gca()
        return [artist]
    phase_animation = animation.FuncAnimation(figure, frame_generation, len(sync_output_dynamic), init_func=init_frame, interval=animation_velocity, repeat_delay=1000)
    if save_movie is not None:
        phase_animation.save(save_movie, writer='ffmpeg', fps=15, bitrate=1500)
    else:
        plt.show()

