def pretty_eta(seconds_left):
    minutes_left = seconds_left // 60
    seconds_left %= 60
    hours_left = minutes_left // 60
    minutes_left %= 60
    days_left = hours_left // 24
    hours_left %= 24

    def helper(cnt, name):
        return '{} {}{}'.format(str(cnt), name, 's' if cnt > 1 else '')
    if days_left > 0:
        msg = helper(days_left, 'day')
        if hours_left > 0:
            msg += ' and ' + helper(hours_left, 'hour')
        return msg
    if hours_left > 0:
        msg = helper(hours_left, 'hour')
        if minutes_left > 0:
            msg += ' and ' + helper(minutes_left, 'minute')
        return msg
    if minutes_left > 0:
        return helper(minutes_left, 'minute')
    return 'less than a minute'

def topDownCompute(self, encoded):
    if self.ncategories == 0:
        return 0
    topDownMappingM = self._getTopDownMapping()
    categoryIndex = topDownMappingM.rightVecProd(encoded).argmax()
    category = self.categories[categoryIndex]
    encoding = topDownMappingM.getRow(categoryIndex)
    return EncoderResult(value=category, scalar=categoryIndex, encoding=encoding)

def intersection(self, other, recursive=True):
    if not isinstance(other, composite):
        raise AssertionError('Cannot intersect composite and {} types'.format(type(other)))
    if self.meta_type != other.meta_type:
        return composite({})
    if self.meta_type == 'list':
        keep = []
        for item in self._list:
            if item in other._list:
                if recursive and isinstance(item, composite):
                    keep.extend(item.intersection(other.index(item), recursive=True))
                else:
                    keep.append(item)
        return composite(keep)
    elif self.meta_type == 'dict':
        keep = {}
        for key in self._dict:
            item = self._dict[key]
            if key in other._dict:
                if recursive and isinstance(item, composite) and isinstance(other.get(key), composite):
                    keep[key] = item.intersection(other.get(key), recursive=True)
                elif item == other[key]:
                    keep[key] = item
        return composite(keep)
    return

def record_drop_duplicate_fields(record):
    out = {}
    position = 0
    tags = sorted(record.keys())
    for tag in tags:
        fields = record[tag]
        out[tag] = []
        current_fields = set()
        for full_field in fields:
            field = (tuple(full_field[0]),) + full_field[1:4]
            if field not in current_fields:
                current_fields.add(field)
                position += 1
                out[tag].append(full_field[:4] + (position,))
    return out

