def Gharagheizi_gas_viscosity(T, Tc, Pc, MW):
    Tr = T / Tc
    mu_g = 1e-05 * Pc * Tr + (0.091 - 0.477 / MW) * T + MW * (1e-05 * Pc - 8 * MW ** 2 / T ** 2) * (10.7639 / Tc - 4.1929 / T)
    return 1e-07 * abs(mu_g)

